// This file was generated by Slater.app - Footer apparition.js


gsap.registerPlugin(ScrollTrigger);

const footerLogo = document.querySelector('.footer_logo_img');

if (footerLogo) {
  gsap.fromTo(footerLogo,
  {
    y: "25rem", // On part d'un peu plus bas pour plus d'amplitude
    opacity: 0
  },
  {
    y: "7rem",
    opacity: 1,
    ease: "none", // Indispensable avec le scrub pour une linéarité parfaite
    scrollTrigger: {
      trigger: ".footer13_component",
      // "top 80%" : L'animation commence quand le haut du footer est à 80% de l'écran (plus tard)
      start: "top 80%",
      // "bottom bottom" : L'animation finit quand le bas du footer touche le bas de l'écran
      end: "bottom bottom",
      scrub: 2, // Augmenté à 2.5 pour une inertie beaucoup plus lourde et smooth
    }
  });
}


